def P(t='',style=None):
    if style is None and re.match(r'^(Figure|Table) \d+\.',t): style='Caption'
    return d.add_paragraph(t,style)
def H(t,n=1):
    # Each top-level item listed in Contents starts on a fresh page.
    front={'Project Declaration','Certificate','Acknowledgement','Abstract','Contents','List of Figures','List of Tables'}
    if n==1 and t=='1. Introduction':
        sec=d.add_section(WD_SECTION.NEW_PAGE)
        sec.top_margin=Inches(.7); sec.bottom_margin=Inches(.7); sec.left_margin=Inches(.85); sec.right_margin=Inches(.85)
        sec.footer.is_linked_to_previous=False
        f=sec.footer.paragraphs[0]; f.clear(); f.alignment=WD_ALIGN_PARAGRAPH.CENTER
        f.add_run('DocuAudit  •  Page ').font.size=Pt(12)
        run=OxmlElement('w:r')
        begin=OxmlElement('w:fldChar'); begin.set(qn('w:fldCharType'),'begin'); begin.set(qn('w:dirty'),'true')
        instr=OxmlElement('w:instrText'); instr.set(qn('xml:space'),'preserve'); instr.text=' PAGE '
        separate=OxmlElement('w:fldChar'); separate.set(qn('w:fldCharType'),'separate')
        result=OxmlElement('w:t'); result.text='1'
        end=OxmlElement('w:fldChar'); end.set(qn('w:fldCharType'),'end')
        for node in (begin,instr,separate,result,end):
            if node is result:
                rr=OxmlElement('w:r'); rr.append(node); f._p.append(rr)
            else:
                rr=OxmlElement('w:r'); rr.append(node); f._p.append(rr)
        pg=OxmlElement('w:pgNumType'); pg.set(qn('w:start'),'1'); sec._sectPr.append(pg)
    elif n==1 and (re.match(r'^\d+\.',t) or t=='References' or t.startswith('Appendix ') or t in front):
        d.add_page_break()
    return d.add_heading(t,n)
def B(t): return P(t,'List Bullet')
def N(t): return P(t,'List Number')
def T(head,rows):
    global table_counter
    table_counter+=1
    tab=d.add_table(rows=1,cols=len(head)); tab.style='Table Grid'; tab.alignment=WD_TABLE_ALIGNMENT.CENTER
    for i,x in enumerate(head):
        c=tab.rows[0].cells[i]; c.text=x; c._tc.get_or_add_tcPr().append(OxmlElement('w:shd')); c._tc.tcPr[-1].set(qn('w:fill'),'17365D')
        for r in c.paragraphs[0].runs: r.bold=True; r.font.color.rgb=RGBColor(255,255,255); r.font.size=Pt(12)
    repeat=OxmlElement('w:tblHeader'); repeat.set(qn('w:val'),'true'); tab.rows[0]._tr.get_or_add_trPr().append(repeat)
    for j,row in enumerate(rows):
        cells=tab.add_row().cells
        for i,x in enumerate(row):
            cells[i].text=str(x); cells[i].vertical_alignment=WD_CELL_VERTICAL_ALIGNMENT.CENTER
            if j%2: cells[i]._tc.get_or_add_tcPr().append(OxmlElement('w:shd')); cells[i]._tc.tcPr[-1].set(qn('w:fill'),'EAF0F6')
            for r in cells[i].paragraphs[0].runs: r.font.size=Pt(12)
            for p in cells[i].paragraphs: p.paragraph_format.line_spacing=1.15
    if table_counter>1:
        cp=d.add_paragraph(style='Caption'); cp.add_run(f'Table {table_counter-1}. {TABLE_TITLES[table_counter-2]}')
        cp.alignment=WD_ALIGN_PARAGRAPH.CENTER
        cp.paragraph_format.keep_together=True
    d.add_paragraph()

def make_dfd():
    # A Level 1 data-flow diagram generated as a crisp embedded PNG.
    im=Image.new('RGB',(1320,760),'white'); dr=ImageDraw.Draw(im)
    try:
        regular=ImageFont.truetype(r'C:\Windows\Fonts\arial.ttf',21)
        bold=ImageFont.truetype(r'C:\Windows\Fonts\arialbd.ttf',22)
        small=ImageFont.truetype(r'C:\Windows\Fonts\arial.ttf',16)
    except OSError:
        regular=bold=small=ImageFont.load_default()
    navy='#17365D'; blue='#DCEAF7'; green='#E4F1E8'; gold='#FFF2CC'; ink='#25364A'; line='#44627F'
    dr.text((35,22),'DocuAudit Level 1 Data Flow Diagram',font=bold,fill=navy)
    def box(xy,label,fill,tag=None):
        dr.rounded_rectangle(xy,radius=18,fill=fill,outline=navy,width=3)
        x1,y1,x2,y2=xy; lines=label.split('\n')
        heights=[dr.textbbox((0,0),z,font=bold)[3] for z in lines]
        y=y1+(y2-y1-sum(heights)-6*(len(lines)-1))//2
        for z,h in zip(lines,heights):
            bb=dr.textbbox((0,0),z,font=bold); w=bb[2]-bb[0]
            dr.text((x1+(x2-x1-w)//2,y),z,font=bold,fill=ink); y+=h+6
        if tag: dr.text((x1+8,y1+7),tag,font=small,fill=navy)
    def store(xy,label):
        x1,y1,x2,y2=xy
        dr.rectangle((x1,y1+12,x2,y2-12),fill=green,outline=navy,width=3)
        dr.ellipse((x1,y1,x2,y1+24),fill=green,outline=navy,width=3)
        dr.arc((x1,y2-24,x2,y2),0,180,fill=navy,width=3)
        dr.text((x1+12,y1+35),label,font=bold,fill=ink)
    def arrow(a,b,label='',offset=(0,0)):
        dr.line((a,b),fill=line,width=4)
        import math
        ang=math.atan2(b[1]-a[1],b[0]-a[0]); L=15
        p1=(b[0]-L*math.cos(ang-.48),b[1]-L*math.sin(ang-.48))
        p2=(b[0]-L*math.cos(ang+.48),b[1]-L*math.sin(ang+.48))
        dr.polygon([b,p1,p2],fill=line)
        if label:
            mx=(a[0]+b[0])//2+offset[0]; my=(a[1]+b[1])//2+offset[1]
            bb=dr.textbbox((0,0),label,font=small); w=bb[2]-bb[0]
            dr.rounded_rectangle((mx-w//2-5,my-3,mx+w//2+5,my+22),radius=4,fill='white')
            dr.text((mx-w//2,my),label,font=small,fill=ink)
    box((25,205,175,315),'User /\nReviewer',gold,'External entity')
    box((245,205,430,315),'API and\nUpload',blue,'1')
    box((545,205,770,315),'Worker and\nExtraction',blue,'2')
    box((875,205,1085,315),'Audit and\nCompliance',blue,'3')
    store((245,470,430,580),'PDF Uploads')
    store((480,470,665,580),'Redis Queue')
    store((705,470,890,580),'Qdrant Vectors')
    store((930,470,1115,580),'PostgreSQL')
    # Primary request/result exchange and internal process sequence.
    arrow((175,240),(245,240),'PDF',(0,-24))
    arrow((245,282),(175,282),'status',(0,18))
    arrow((770,245),(875,245),'fields',(0,-24))
    arrow((875,285),(770,285),'repair',(0,18))
    # Data-store flows are separated below the process row to avoid crossing labels.
    arrow((337,315),(337,470),'PDF',(-55,0))
    arrow((430,300),(520,470),'job',(10,-4))
    arrow((625,470),(625,315),'job',(52,0))
    arrow((735,315),(795,470),'vectors',(40,-4))
    arrow((850,470),(850,315),'chunks',(58,0))
    arrow((980,315),(1020,470),'save',(30,-4))
    arrow((1060,470),(1060,315),'lookup',(56,0))
    # Completed status is returned to the API and shown to the user.
    dr.line([(980,205),(980,140),(340,140),(340,205)],fill=line,width=4)
    arrow((340,140),(340,205),'results via DB',(330,-8))
    dr.text((25,635),'Data stores: cylinders. Arrows are labelled with the data exchanged.',font=small,fill=ink)
    dr.text((25,675),'PDFs persist in the shared volume; Redis carries jobs; Qdrant stores vectors; PostgreSQL stores workflow results.',font=small,fill=ink)
    preview=OUT.parent/'report_render'/'docuaudit_dfd_preview.png'
    preview.parent.mkdir(exist_ok=True)
    im.save(preview,dpi=(180,180))
    buf=BytesIO(); im.save(buf,format='PNG',dpi=(180,180)); buf.seek(0); return buf

