    arrow((600,260),(250,430),'store and read PDF',(-15,0))
    arrow((650,260),(535,430),'document state',(10,0))
    arrow((1160,260),(850,430),'index / retrieve',(5,0))
    arrow((1230,260),(1160,430),'model inference',(70,0))
    dr.text((35,625),'Blue: application services    Green: storage and model services    Gold: external actor',font=small,fill=ink)
    preview=OUT.parent/'report_render'/'docuaudit_architecture_preview.png'; preview.parent.mkdir(exist_ok=True)
