def _diagram_canvas(size,title):
    im=Image.new('RGB',size,'white'); dr=ImageDraw.Draw(im)
    try:
        regular=ImageFont.truetype(r'C:\Windows\Fonts\arial.ttf',20)
        bold=ImageFont.truetype(r'C:\Windows\Fonts\arialbd.ttf',23)
        small=ImageFont.truetype(r'C:\Windows\Fonts\arial.ttf',16)
    except OSError:
        regular=bold=small=ImageFont.load_default()
    navy='#17365D'; blue='#DCEAF7'; green='#E4F1E8'; gold='#FFF2CC'; ink='#25364A'; line='#44627F'; pale='#F4F7FA'
    dr.text((32,20),title,font=bold,fill=navy)
    return im,dr,regular,bold,small,navy,blue,green,gold,ink,line,pale

def _diagram_box(dr,xy,title,lines,fill,navy,ink,bold,regular,small=None):
    dr.rounded_rectangle(xy,radius=18,fill=fill,outline=navy,width=3)
    x1,y1,x2,y2=xy
    dr.text((x1+16,y1+12),title,font=bold,fill=navy)
    y=y1+50
    for value in lines:
        dr.text((x1+18,y),value,font=regular,fill=ink); y+=31

def _diagram_bytes(im,name):
    preview=OUT.parent/'report_render'/name; preview.parent.mkdir(exist_ok=True)
    im.save(preview,dpi=(180,180))
    buf=BytesIO(); im.save(buf,format='PNG',dpi=(180,180)); buf.seek(0); return buf

