def make_processing_workflow():
    im,dr,regular,bold,small,navy,blue,green,gold,ink,line,pale=_diagram_canvas((1500,700),'Invoice Processing Workflow')
    top=[('1  Upload',['PDF saved','document ID']),('2  Queue',['Celery task','status: pending']),('3  Ingest',['PyMuPDF text','shared upload']),('4  Retrieve',['Qdrant lookup','document filter'])]
    bottom=[('8  Recheck + state',['rerun compliance/audit','complete or needs_review']),('7  Repair',['one bounded pass','verified candidate']),('6  Compliance + audit',['rules, evidence','and optional NLI']),('5  Extract',['seven schema fields','QA model'])]
    x0=55; w=300; gap=45; y1=135; y2=405; h=155
    for i,(title,lines) in enumerate(top):
        x=x0+i*(w+gap); _diagram_box(dr,(x,y1,x+w,y1+h),title,lines,blue,navy,ink,bold,regular)
        if i<3:
            sx=x+w; ex=x+w+gap
            dr.line((sx,y1+78,ex,y1+78),fill=line,width=4); dr.polygon([(ex,y1+78),(ex-14,y1+69),(ex-14,y1+87)],fill=line)
    # The workflow turns down after retrieval and continues right-to-left on the second row.
    dr.line((1325,y1+h,1325,y2-20),fill=line,width=4); dr.polygon([(1325,y2-20),(1316,y2-36),(1334,y2-36)],fill=line)
    for i,(title,lines) in enumerate(bottom):
        x=x0+i*(w+gap); fill=gold if i in (0,1) else green if i==2 else blue
        _diagram_box(dr,(x,y2,x+w,y2+h),title,lines,fill,navy,ink,bold,regular)
        if i<3:
            sx=x+w+gap; ex=x+w
            dr.line((sx,y2+78,ex,y2+78),fill=line,width=4); dr.polygon([(ex,y2+78),(ex+14,y2+69),(ex+14,y2+87)],fill=line)
    dr.text((56,625),'If all fields pass, review is skipped. Otherwise one candidate-repair pass runs, followed by compliance and audit again.',font=small,fill=ink)
    return _diagram_bytes(im,'docuaudit_processing_workflow.png')

