    im,dr,regular,bold,small,navy,blue,green,gold,ink,line,pale=_diagram_canvas((1400,560),'Evaluation Dataset Profile')
    _diagram_box(dr,(40,115,440,345),'Final benchmark',['27 synthetic invoice PDFs','186 labelled field values','Golden labels: JSON'],blue,navy,ink,bold,regular)
