def make_evaluation_workflow():
    im,dr,regular,bold,small,navy,blue,green,gold,ink,line,pale=_diagram_canvas((1500,490),'Evaluation and Regression-Gate Workflow')
    cards=[('Gold labels',['Expected fields','Expected flags']),('Run pipeline',['Ingest + index','Invoke graph']),('Compare',['Field values','Audit + flags']),('Score',['F1 + coverage','Precision + flags']),('Gate',['Compare limits','Fail or pass'])]
    x0=45; w=245; gap=48; y=145; h=180
    for i,(title,lines) in enumerate(cards):
        x=x0+i*(w+gap)
        fill=gold if i==0 else green if i==4 else blue
        _diagram_box(dr,(x,y,x+w,y+h),title,lines,fill,navy,ink,bold,regular)
        if i<len(cards)-1:
            sx=x+w; ex=x+w+gap
            dr.line((sx,y+90,ex,y+90),fill=line,width=4)
            dr.polygon([(ex,y+90),(ex-13,y+82),(ex-13,y+98)],fill=line)
    dr.rounded_rectangle((170,375,1330,455),radius=15,fill=pale,outline='#AAB7C4',width=2)
    dr.text((195,398),'Safety gate: any verified error, flag mismatch, or missing-field failure can fail the configured benchmark.',font=regular,fill=ink)
    return _diagram_bytes(im,'docuaudit_evaluation_workflow.png')

